cmd:
cd /app/doomgeneric/doomgeneric && python3 - <<'EOF'
src = open('doomgeneric_img.c').read()
# fix the unbalanced brace in DG_SleepMs: remove the stray '{' left over from my patch
src = src.replace('''void DG_SleepMs(uint32_t ms)
{
    (void)ms;
    return;
    {
    // Spinloop implementation''', '''void DG_SleepMs(uint32_t ms)
{
    (void)ms;
    return;
    if (0) {
    // Spinloop implementation''')
open('doomgeneric_img.c','w').write(src)
EOF
mips-linux-gnu-gcc -mips32 -O2 -ffunction-sections -fdata-sections -c doomgeneric_img.c 2>&1 | head -20; echo rc=$?

cd /app/doomgeneric/doomgeneric && cat > /tmp/iwads.c <<'EOF'
char *D_FindIWAD(int mask, void *mission)
{
    (void)mask; (void)mission;
    return "doom.wad";
}
EOF
mips-linux-gnu-gcc -mips32 -O2 -ffunction-sections -fdata-sections -c /tmp/iwads.c -o iwads.o && mips-linux-gnu-gcc -mips32 -O2 -nostdlib -Wl,--gc-sections -Ttext=0x10000 -o doomgeneric_mips /tmp/crt0.S *.o && rm -f doomgeneric_mips.orig; echo LINK_OK

cd /app/doomgeneric/doomgeneric && cat > iwads_stub.c <<'EOF'
char *getenv(const char *name)
{
    (void)name;
    return 0;
}
EOF
mips-linux-gnu-gcc -mips32 -O2 -ffunction-sections -fdata-sections -c iwads_stub.c -o iwads_stub.o && mips-linux-gnu-gcc -mips32 -O2 -nostdlib -Wl,--gc-sections -Ttext=0x10000 -o doomgeneric_mips /tmp/crt0.S *.o 2>&1 | grep -v "cprestore"; echo LINK_OK; ls -la doomgeneric_mips
